#include <vector>
#include <stdexcept>

int obtener(std::mt19937& motor, int minimo, int maximo) {
    if (minimo < -12 || minimo > 12 || maximo < -12 || maximo > 12
            || minimo > maximo) {
        throw std::invalid_argument("Intervalo invalido");
    }
    std::uniform_int_distribution<int> elegir{minimo, maximo};
    return elegir(motor);
}

int main() {
    std::mt19937 motor{127};
    const std::mt19937 guardado = motor;
    try {
        const int dato = obtener(motor, 6, 2);
        std::cout << "Dato:" << dato;
    } catch (const std::invalid_argument&) {
        std::cout << "Rechazado:" << (motor == guardado);
    }
    return 0;
}

