}

int main() {
    std::mt19937 por_lotes{191};
    const std::vector<int> primero = generar(por_lotes, 4, -2, 5);
    std::mt19937 continuacion = por_lotes;
    const std::vector<int> segundo = generar(por_lotes, 3, -2, 5);
