            || maximo < -12 || maximo > 12 || minimo > maximo) {
        throw std::invalid_argument("Configuracion invalida");
    }
    std::uniform_int_distribution<int> elegir{minimo, maximo};
    std::vector<int> datos;
    for (int i{0}; i < cantidad; ++i) {
        datos.push_back(elegir(motor));
    }
    return datos;
}

void probar(int cantidad,int minimo,int maximo) {
    std::mt19937 motor{191};
    const std::mt19937 antes=motor;
    try {
        const std::vector<int> primero=generar(motor,cantidad,minimo,maximo);
        std::mt19937 copia=motor;
        const std::vector<int> segundo=generar(motor,3,minimo,maximo);
        const std::vector<int> repetido=generar(copia,3,minimo,maximo);
        bool rango=true;
        for(int dato:primero) { rango=rango && dato>=minimo && dato<=maximo; }
        for(int dato:segundo) { rango=rango && dato>=minimo && dato<=maximo; }
        const std::mt19937 antes_vacio=motor;
        const std::vector<int> vacio=generar(motor,0,minimo,maximo);
        std::cout<<"Cantidad:"<<primero.size()<<";Rango:"<<rango
                 <<";Continuacion:"<<(segundo==repetido && motor==copia)
                 <<";Vacio:"<<vacio.size()<<":"<<(motor==antes_vacio);
        const std::mt19937 antes_error=motor;
        try {
            const std::vector<int> invalido=generar(motor,3,5,2);
            std::cout<<";Aceptado:"<<invalido.size();
        } catch(const std::invalid_argument&) {
            std::cout<<";Rechazo:"<<(motor==antes_error);
        }
